ية","en":"Starting policies","min":1e-06,"step":0.01}],"sort_order":33005},{"slug":"insurance-loss-cost-per-policy-calculator","title_ar":"حاسبة تكلفة الخسائر لكل وثيقة","title_en":"Insurance Loss Cost per Policy Calculator","expression":"loss_cost / policies","fields":[{"key":"loss_cost","ar":"إجمالي تكلفة الخسائر","en":"Total loss cost","min":0,"step":0.01},{"key":"policies","ar":"عدد الوثائق","en":"Policies","min":1e-06,"step":0.01}],"sort_order":33006},{"slug":"insurance-premium-per-customer-calculator","title_ar":"حاسبة القسط لكل عميل","title_en":"Insurance Premium per Customer Calculator","expression":"premium_revenue / customers","fields":[{"key":"premium_revenue","ar":"إجمالي الأقساط","en":"Premium revenue","min":0,"step":0.01},{"key":"customers","ar":"عدد العملاء","en":"Customers","min":1e-06,"step":0.01}],"sort_order":33007},{"slug":"insurance-claims-per-thousand-policies-calculator","title_ar":"حاسبة المطالبات لكل ألف وثيقة","title_en":"Insurance Claims per 1,000 Policies Calculator","expression":"claims / policies * 1000","fields":[{"key":"claims","ar":"المطالبات","en":"Claims","min":0,"step":0.01},{"key":"policies","ar":"الوثائق","en":"Policies","min":1e-06,"step":0.01}],"sort_order":33008},{"slug":"insurance-operating-cost-ratio-calculator","title_ar":"حاسبة نسبة تكلفة تشغيل التأمين","title_en":"Insurance Operating Cost Ratio Calculator","expression":"operating_cost / premium_revenue * 100","fields":[{"key":"operating_cost","ar":"تكلفة التشغيل","en":"Operating cost","min":0,"step":0.01},{"key":"premium_revenue","ar":"إيراد الأقساط","en":"Premium revenue","min":1e-06,"step":0.01}],"sort_order":33009},{"slug":"insurance-net-underwriting-margin-calculator","title_ar":"حاسبة هامش الاكتتاب الصافي","title_en":"Insurance Net Underwriting Margin Calculator","expression":"(premium_revenue - claims_cost - operating_cost) / premium_revenue * 100","fields":[{"key":"premium_revenue","ar":"إيراد الأقساط","en":"Premium revenue","min":1e-06,"step":0.01},{"key":"claims